CREATE OR REPLACE FUNCTION private.org_config() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT config FROM base_org_state WHERE id),'{}'::jsonb) || jsonb_build_object('units',(SELECT coalesce(jsonb_agg((data-'parent_id')||jsonb_strip_nulls(jsonb_build_object('id',id,'parent_id',parent_id,'kind',kind,'name',name,'active',active,'source',source)) ORDER BY id),'[]') FROM org_units),'titles',(SELECT coalesce(jsonb_agg((data-'unit_id')||jsonb_strip_nulls(jsonb_build_object('id',id,'unit_id',unit_id,'name',name,'code',code,'level',level,'kind',kind,'capacity',capacity,'active',active,'source',source)) ORDER BY id),'[]') FROM org_titles),'memberships',(SELECT coalesce(jsonb_agg((data-'ends_at'-'title_id'-'kind')||jsonb_strip_nulls(jsonb_build_object('id',id,'unit_id',unit_id,'title_id',title_id,'user_id',user_id,'category',category,'kind',CASE WHEN category IN ('primary','concurrent') THEN category END,'starts_at',starts_at,'ends_at',ends_at,'active',status<>'cancelled' AND (ends_at IS NULL OR ends_at>now()),'status',status,'source',source)) ORDER BY id),'[]') FROM org_assignments),'defaults',coalesce((SELECT config->'defaults' FROM base_org_state WHERE id),'[]'),'bundles',coalesce((SELECT config->'bundles' FROM base_org_state WHERE id),'[]'),'grants',coalesce((SELECT config->'grants' FROM base_org_state WHERE id),'[]'),'bindings',coalesce((SELECT config->'bindings' FROM base_org_state WHERE id),'[]')); $$;
CREATE OR REPLACE FUNCTION private.org_contains(root_id text,target_id text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE tree AS (SELECT id,ARRAY[id] path FROM org_units WHERE id=root_id AND active UNION ALL SELECT u.id,t.path||u.id FROM org_units u JOIN tree t ON u.parent_id=t.id WHERE u.active AND NOT u.id=ANY(t.path)) SELECT EXISTS(SELECT 1 FROM tree WHERE id=target_id) $$;
CREATE OR REPLACE FUNCTION private.org_can(u uuid,p text,target_id text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE rules jsonb;BEGIN IF u IS NULL OR NOT private.is_active(u) THEN RETURN false;END IF; IF private.is_super_admin(u) THEN RETURN true; END IF; IF NOT EXISTS(SELECT 1 FROM org_units WHERE id=target_id AND active) THEN RETURN false; END IF; rules:=private.base_rules(u,private.org_config()); RETURN NOT EXISTS(SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>'permission'=p AND r->>'effect'='DENY' AND (nullif(r->>'unit_id','') IS NULL OR private.org_contains(r->>'unit_id',target_id))) AND EXISTS(SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>'permission'=p AND r->>'effect'='ALLOW' AND (nullif(r->>'unit_id','') IS NULL OR private.org_contains(r->>'unit_id',target_id))); END $$;
CREATE OR REPLACE FUNCTION private.base_org_units_below(c jsonb,unit text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE tree AS (SELECT x->>'id' id,ARRAY[x->>'id'] path FROM jsonb_array_elements(c->'units') x WHERE x->>'id'=unit AND coalesce((x->>'active')::boolean,false) UNION ALL SELECT x->>'id',t.path||(x->>'id') FROM jsonb_array_elements(c->'units') x JOIN tree t ON x->>'parent_id'=t.id WHERE coalesce((x->>'active')::boolean,false) AND NOT (x->>'id'=ANY(t.path))) SELECT coalesce(jsonb_agg(id),'[]') FROM tree $$;
CREATE OR REPLACE FUNCTION private.base_rules(u uuid,c jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE tree AS (SELECT x FROM jsonb_array_elements(c->'units') x WHERE x->>'kind' IN ('block','company') AND coalesce((x->>'active')::boolean,false) UNION SELECT child.value FROM jsonb_array_elements(c->'units') child(value) JOIN tree t ON child.value->>'parent_id'=t.x->>'id' WHERE coalesce((child.value->>'active')::boolean,false)),member AS (SELECT m FROM jsonb_array_elements(c->'memberships') m WHERE m->>'user_id'=u::text AND private.base_valid_at(m) AND EXISTS(SELECT 1 FROM tree WHERE x->>'id'=m->>'unit_id')),ancestors AS (SELECT x->>'id' id,x->>'parent_id' parent_id FROM tree JOIN member ON x->>'id'=member.m->>'unit_id' UNION SELECT t.x->>'id',t.x->>'parent_id' FROM tree t JOIN ancestors a ON t.x->>'id'=a.parent_id),rules AS (SELECT r||jsonb_build_object('source_kind','direct','source_id',r->>'id') r FROM jsonb_array_elements(c->'grants') r WHERE r->>'user_id'=u::text UNION ALL SELECT r||jsonb_build_object('source_kind','default','source_id',d->>'id','source_name',d->>'name') FROM jsonb_array_elements(c->'defaults') d CROSS JOIN LATERAL jsonb_array_elements(d->'rules') r WHERE private.base_valid_at(d) AND ((d->>'unit_id' IS NOT NULL AND EXISTS(SELECT 1 FROM ancestors WHERE id=d->>'unit_id')) OR (d->>'title_id' IS NOT NULL AND EXISTS(SELECT 1 FROM member WHERE m->>'title_id'=d->>'title_id') AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'titles') t WHERE t->>'id'=d->>'title_id' AND coalesce((t->>'active')::boolean,false)))) UNION ALL SELECT r||jsonb_build_object('source_kind','bundle','source_id',b->>'id','source_name',b->>'name') FROM jsonb_array_elements(c->'bindings') a JOIN LATERAL jsonb_array_elements(c->'bundles') b ON b->>'id'=a->>'bundle_id' CROSS JOIN LATERAL jsonb_array_elements(b->'rules') r WHERE a->>'user_id'=u::text AND private.base_valid_at(a) AND private.base_valid_at(b)) SELECT coalesce(jsonb_agg(r),'[]') FROM rules WHERE private.base_valid_at(r) $$;
CREATE OR REPLACE FUNCTION public.org_workspace_read() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;super_ boolean;visible text[];assign_ text[];appoint_ text[];structure_ text[];history_ text[];configured boolean;BEGIN IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) THEN RAISE EXCEPTION 'Vui lòng đăng nhập lại.';END IF;super_:=private.is_super_admin(auth.uid());c:=private.org_config(); SELECT coalesce(array_agg(id),'{}') INTO assign_ FROM org_units WHERE private.org_can(auth.uid(),'org.assign_staff',id); SELECT coalesce(array_agg(id),'{}') INTO appoint_ FROM org_units WHERE private.org_can(auth.uid(),'org.appoint_manager',id); SELECT coalesce(array_agg(id),'{}') INTO structure_ FROM org_units WHERE private.org_can(auth.uid(),'org.manage_structure',id); SELECT coalesce(array_agg(id),'{}') INTO history_ FROM org_units WHERE private.org_can(auth.uid(),'org.view_history',id); SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(private.base_rules(auth.uid(),c)) r WHERE r->>'permission' LIKE 'org.%') INTO configured; SELECT coalesce(array_agg(id),'{}') INTO visible FROM org_units WHERE super_ OR private.org_can(auth.uid(),'org.view',id) OR id=ANY(assign_||appoint_||structure_) OR NOT configured;
 c:=c||jsonb_build_object('units',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(c->'units') x WHERE x->>'id'=ANY(visible)),'titles',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(c->'titles') x WHERE super_ OR x->>'unit_id'=ANY(visible) OR (x->>'unit_id' IS NULL AND EXISTS(SELECT 1 FROM org_units u WHERE u.id=ANY(visible) AND (u.kind=x->>'unit_kind' OR (x->>'unit_kind'='individual' AND u.kind IN ('department','team')))))),'memberships',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(c->'memberships') x WHERE x->>'unit_id'=ANY(visible) AND (super_ OR x->>'unit_id'=ANY(history_) OR ((x->>'active')::boolean AND (nullif(x->>'starts_at','') IS NULL OR (x->>'starts_at')::timestamptz<=now())))));
 IF NOT super_ THEN c:=c||jsonb_build_object('defaults','[]'::jsonb,'grants','[]'::jsonb,'bindings','[]'::jsonb,'bundles','[]'::jsonb);END IF;
 RETURN jsonb_build_object('revision',(SELECT revision FROM private.org_control WHERE id),'server_now',now(),'config',c,'staff',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',full_name,'status',status)),'[]') FROM profiles WHERE super_ OR cardinality(assign_||appoint_)>0 OR id IN (SELECT user_id FROM org_assignments WHERE unit_id=ANY(visible) AND (ends_at IS NULL OR ends_at>now()) AND (starts_at IS NULL OR starts_at<=now()))),'catalog',(SELECT coalesce(jsonb_agg(jsonb_build_object('key',key,'label',label,'module',module,'supported',private.base_supported(key))),'[]') FROM base_permission_catalog WHERE super_),'actor',jsonb_build_object('super',super_,'assign_all',super_,'appoint_all',super_,'assign_units',assign_,'appoint_units',appoint_,'structure_units',structure_,'view_history',cardinality(history_)>0,'history_units',history_),'events',(SELECT coalesce(jsonb_agg(to_jsonb(e)),'[]') FROM (SELECT * FROM org_events e WHERE super_ OR (jsonb_array_length(e.unit_ids)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(e.unit_ids) u WHERE NOT u=ANY(history_))) ORDER BY created_at DESC LIMIT 100)e));END $$;
CREATE POLICY org_unit_read ON org_units FOR SELECT TO authenticated USING(private.org_can(auth.uid(),'org.view',id)); CREATE POLICY org_title_read ON org_titles FOR SELECT TO authenticated USING(private.org_can(auth.uid(),'org.view',unit_id)); CREATE POLICY org_assignment_read ON org_assignments FOR SELECT TO authenticated USING(private.org_can(auth.uid(),'org.view_history',unit_id) OR (private.org_can(auth.uid(),'org.view',unit_id) AND (starts_at IS NULL OR starts_at<=now()) AND (ends_at IS NULL OR ends_at>now()))); CREATE POLICY org_parent_read ON org_parent_history FOR SELECT TO authenticated USING(private.org_can(auth.uid(),'org.view_history',unit_id)); CREATE POLICY org_event_read ON org_events FOR SELECT TO authenticated USING(private.is_super_admin(auth.uid()) OR (jsonb_array_length(unit_ids)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(unit_ids) u WHERE NOT private.org_can(auth.uid(),'org.view_history',u))));
REVOKE ALL ON FUNCTION private.org_config(),private.org_contains(text,text),private.org_can(uuid,text,text) FROM PUBLIC,anon; REVOKE ALL ON FUNCTION private.org_config(),private.org_contains(text,text) FROM authenticated,service_role; GRANT EXECUTE ON FUNCTION private.org_can(uuid,text,text) TO authenticated; REVOKE ALL ON FUNCTION org_workspace_read() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION org_workspace_read() TO authenticated,service_role;